import{_ as t,o as a,a as o,d as r}from"./chunks/framework.IehvnstE.js";const m=JSON.parse('{"title":"FAQ","description":"Frequently asked questions about Stuzhik. Troubleshooting: OutOfMemoryError, crashes, mod conflicts. Supports Forge, Fabric, NeoForge and Quilt.","frontmatter":{"description":"Frequently asked questions about Stuzhik. Troubleshooting: OutOfMemoryError, crashes, mod conflicts. Supports Forge, Fabric, NeoForge and Quilt.","head":[["meta",{"name":"keywords","content":"stuzhik faq, minecraft launcher problems, outofmemoryerror minecraft, minecraft mods crash, forge fabric quilt neoforge"}]]},"headers":[],"relativePath":"en/faq.md","filePath":"en/faq.md"}'),n={name:"en/faq.md"};function i(s,e,h,d,l,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><p>Short answers to common questions. Each topic has its guide page, linked from the answers.</p><h2 id="general-questions" tabindex="-1">General questions <a class="header-anchor" href="#general-questions" aria-label="Permalink to &quot;General questions&quot;">​</a></h2><h3 id="how-is-it-different-from-other-launchers" tabindex="-1">How is it different from other launchers? <a class="header-anchor" href="#how-is-it-different-from-other-launchers" aria-label="Permalink to &quot;How is it different from other launchers?&quot;">​</a></h3><ul><li><strong>Crash analysis.</strong> Names the mod that crashed the game and gives steps with buttons. Other launchers only show the log</li><li><strong>Live monitoring.</strong> Shows errors while you play, before a crash</li><li><strong>Stuzhik Connect.</strong> Take a build from a friend directly, without uploading it to third-party services: <a href="/en/guide/connect.html">Stuzhik Connect</a></li><li><strong>Mod collections.</strong> Sets of mods not tied to a version, applied to any instance with one click: <a href="/en/guide/collections.html">Mod Collections</a></li><li><strong>Light.</strong> Starts fast and uses little</li></ul><h3 id="are-fabric-forge-neoforge-quilt-supported" tabindex="-1">Are Fabric/Forge/NeoForge/Quilt supported? <a class="header-anchor" href="#are-fabric-forge-neoforge-quilt-supported" aria-label="Permalink to &quot;Are Fabric/Forge/NeoForge/Quilt supported?&quot;">​</a></h3><p><strong>Yes, all four, and Minecraft without a loader.</strong></p><h3 id="can-i-use-it-with-existing-instances" tabindex="-1">Can I use it with existing instances? <a class="header-anchor" href="#can-i-use-it-with-existing-instances" aria-label="Permalink to &quot;Can I use it with existing instances?&quot;">​</a></h3><p><strong>Yes.</strong> Import from:</p><ul><li>MultiMC and Prism Launcher</li><li>Modrinth modpacks (<code>.mrpack</code>)</li><li>CurseForge modpacks (<code>.zip</code>)</li></ul><h3 id="do-i-need-a-minecraft-account" tabindex="-1">Do I need a Minecraft account? <a class="header-anchor" href="#do-i-need-a-minecraft-account" aria-label="Permalink to &quot;Do I need a Minecraft account?&quot;">​</a></h3><p>Yes, a Microsoft account that owns Minecraft: Java Edition.</p><h3 id="what-does-stuzhik-send-about-itself" tabindex="-1">What does Stuzhik send about itself? <a class="header-anchor" href="#what-does-stuzhik-send-about-itself" aria-label="Permalink to &quot;What does Stuzhik send about itself?&quot;">​</a></h3><p><strong>Only anonymous statistics, and only with your consent.</strong> On first launch the launcher shows the user agreement, and nothing is sent until you answer.</p><ul><li><strong>Once a day:</strong> the launcher version and its channel, the operating system and its bitness, the interface language, «first launch of the day, week, month» marks, the date of the first launch, the invitation code if you came by one, and your answer to «How did you hear about Stuzhik?» if you gave one</li><li><strong>While the launcher is open:</strong> a short pulse, a random session number (new at every launch) and which Minecraft versions with which loaders are running right now</li></ul><p><strong>Nothing personal is there</strong>: no nickname, no accounts, no build names, none of your files and no persistent install identifier. The server does not store IP addresses, it only looks up the country from them. The full list is in the agreement itself. To turn it off: Settings → Privacy → «Send anonymous statistics», the launcher works the same without it.</p><h3 id="how-do-i-remove-stuzhik-completely" tabindex="-1">How do I remove Stuzhik completely? <a class="header-anchor" href="#how-do-i-remove-stuzhik-completely" aria-label="Permalink to &quot;How do I remove Stuzhik completely?&quot;">​</a></h3><p>Like any program: Windows Settings → Apps → Stuzhik → Uninstall. Service data, saved account logins and the firewall rule always go. <strong>Builds and worlds are deleted only if you tick</strong> «Also delete builds and worlds (all launcher data)». More: <a href="/en/guide/installation.html#uninstalling">Uninstalling</a>.</p><h2 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h2><h3 id="why-does-forge-take-so-long-to-install" tabindex="-1">Why does Forge take so long to install? <a class="header-anchor" href="#why-does-forge-take-so-long-to-install" aria-label="Permalink to &quot;Why does Forge take so long to install?&quot;">​</a></h3><p>The Forge installer downloads libraries from <code>maven.minecraftforge.net</code>, that is 1-3 minutes. Stuzhik speeds it up with BMCLAPI mirrors.</p><h3 id="how-much-space-does-an-instance-take" tabindex="-1">How much space does an instance take? <a class="header-anchor" href="#how-much-space-does-an-instance-take" aria-label="Permalink to &quot;How much space does an instance take?&quot;">​</a></h3><table tabindex="0"><thead><tr><th>What</th><th>Size</th></tr></thead><tbody><tr><td>Minecraft</td><td>~200 MB</td></tr><tr><td>Forge or Fabric</td><td>~50 MB</td></tr><tr><td>Mods (10-50)</td><td>~100-500 MB</td></tr><tr><td><strong>Total</strong></td><td><strong>~400-800 MB</strong></td></tr></tbody></table><h3 id="can-i-run-several-instances-at-the-same-time" tabindex="-1">Can I run several instances at the same time? <a class="header-anchor" href="#can-i-run-several-instances-at-the-same-time" aria-label="Permalink to &quot;Can I run several instances at the same time?&quot;">​</a></h3><p>Yes, with no limits.</p><h2 id="mods" tabindex="-1">Mods <a class="header-anchor" href="#mods" aria-label="Permalink to &quot;Mods&quot;">​</a></h2><h3 id="how-do-i-install-a-mod" tabindex="-1">How do I install a mod? <a class="header-anchor" href="#how-do-i-install-a-mod" aria-label="Permalink to &quot;How do I install a mod?&quot;">​</a></h3><p>The build page → «Mods» → «Catalog» → find the mod → «Install». <strong>Its dependencies come with it.</strong> Your own <code>.jar</code> can be dropped onto the window. More: <a href="/en/guide/mods.html">Mods</a>.</p><h3 id="does-stuzhik-update-mods-automatically" tabindex="-1">Does Stuzhik update mods automatically? <a class="header-anchor" href="#does-stuzhik-update-mods-automatically" aria-label="Permalink to &quot;Does Stuzhik update mods automatically?&quot;">​</a></h3><p><strong>Only mods with auto-update on</strong> (the icon in the mod&#39;s row): a found update installs when updates are checked. Whether new mods get it is decided in «Settings → Mods». <strong>A pinned version is never updated.</strong></p><h3 id="what-do-i-do-about-a-mod-conflict" tabindex="-1">What do I do about a mod conflict? <a class="header-anchor" href="#what-do-i-do-about-a-mod-conflict" aria-label="Permalink to &quot;What do I do about a mod conflict?&quot;">​</a></h3><ul><li><strong>The «Dependencies» tab</strong>: missing dependencies, incompatible pairs and mods «Not for this build» (another game version or loader)</li><li><strong>«Overlaps»</strong>: mods that change the same code or give different items for one craft</li><li>The game has already crashed: the <a href="/en/guide/log-analyzer.html">Log Analyzer</a> names the culprit and offers to update or disable it with a button</li></ul><h3 id="where-are-mods-stored" tabindex="-1">Where are mods stored? <a class="header-anchor" href="#where-are-mods-stored" aria-label="Permalink to &quot;Where are mods stored?&quot;">​</a></h3><p>In the build&#39;s folder inside the launcher&#39;s data folder: <code>instances/&lt;build&gt;/mods</code>. Where the data folder is and how to move it to another drive is below.</p><h3 id="can-i-move-the-launcher-s-data-to-another-drive" tabindex="-1">Can I move the launcher&#39;s data to another drive? <a class="header-anchor" href="#can-i-move-the-launcher-s-data-to-another-drive" aria-label="Permalink to &quot;Can I move the launcher&#39;s data to another drive?&quot;">​</a></h3><p><strong>Yes:</strong> «Settings → Storage → Location». Builds, worlds, Java, the database and logs move together: on the same drive instantly, to another one by copying with every file checked, after which the old folder is removed. New installs on Windows keep their data next to the program from the start. More: <a href="/en/guide/instances.html#data-location">Where the data is</a>.</p><h3 id="is-there-a-portable-mode" tabindex="-1">Is there a portable mode? <a class="header-anchor" href="#is-there-a-portable-mode" aria-label="Permalink to &quot;Is there a portable mode?&quot;">​</a></h3><p><strong>Yes.</strong> Put a file <code>portable.txt</code> next to the program: all the data, the interface settings included, goes into the <code>data</code> folder next to it. That way the launcher can live on a USB stick.</p><h3 id="is-there-stuzhik-for-linux" tabindex="-1">Is there Stuzhik for Linux? <a class="header-anchor" href="#is-there-stuzhik-for-linux" aria-label="Permalink to &quot;Is there Stuzhik for Linux?&quot;">​</a></h3><p><strong>Yes, since 0.0.24</strong> (beta for now): the AppImage, .deb and .rpm on the <a href="/en/download.html#linux">download page</a>. It needs x86_64 and glibc 2.38 or newer: Debian 13, Ubuntu 24.04, Fedora 39 or newer.</p><p>For servers there is the <a href="/en/guide/cli.html">console version</a> <code>stuzhik-cli</code>: it creates, installs and runs servers on any loader, works as a systemd service, analyzes logs and runs on any Linux, ARM included.</p><h3 id="can-discord-show-what-i-m-playing" tabindex="-1">Can Discord show what I&#39;m playing? <a class="header-anchor" href="#can-discord-show-what-i-m-playing" aria-label="Permalink to &quot;Can Discord show what I&#39;m playing?&quot;">​</a></h3><p>Yes, in «Settings → Discord». While the game runs, your profile shows «Playing Stuzhik» with the Minecraft version, the loader and the time in game. You choose what exactly to show and see right there how others will see it.</p><p><strong>On a public server friends can ask to join you through Discord</strong>: their launcher installs the build they need and connects them to the server right away.</p><h2 id="stuzhik-connect" tabindex="-1">Stuzhik Connect <a class="header-anchor" href="#stuzhik-connect" aria-label="Permalink to &quot;Stuzhik Connect&quot;">​</a></h2><h3 id="is-it-safe" tabindex="-1">Is it safe? <a class="header-anchor" href="#is-it-safe" aria-label="Permalink to &quot;Is it safe?&quot;">​</a></h3><p><strong>Yes.</strong> The connection is encrypted entirely (QUIC with TLS 1.3), the launcher recognizes a friend by a signature made with their key, and <strong>a build is taken from you only after you click «Allow»</strong> (that is the default; in the «Sharing modpacks» settings, «Ask for permission» can be switched to «Except friends» or «Never»). Executable files are never transferred. More: <a href="/en/guide/connect.html#security">Stuzhik Connect</a>.</p><h3 id="do-i-need-to-open-ports-on-my-router" tabindex="-1">Do I need to open ports on my router? <a class="header-anchor" href="#do-i-need-to-open-ports-on-my-router" aria-label="Permalink to &quot;Do I need to open ports on my router?&quot;">​</a></h3><p><strong>No.</strong> On a local network devices find each other by themselves. For friends outside your network (different homes, cities) a shared VPN is the easiest, and then there are no ports to forward either: in Radmin VPN, ZeroTier and Hamachi discovery works like on a LAN, and in Tailscale you add your friend by address once, after that the launcher finds them by itself.</p><p>On Windows you need one firewall rule, «Stuzhik Connect»: the button in the «Friends» section adds it.</p><h3 id="does-it-work-directly-over-the-internet-without-a-vpn" tabindex="-1">Does it work directly over the internet, without a VPN? <a class="header-anchor" href="#does-it-work-directly-over-the-internet-without-a-vpn" aria-label="Permalink to &quot;Does it work directly over the internet, without a VPN?&quot;">​</a></h3><p><strong>No, if you are on different networks.</strong> Stuzhik has no server of its own for connecting over the internet: it finds and connects devices only within one network, real or virtual through a VPN. On the same LAN it just works, on different networks you need a shared VPN: <a href="/en/guide/connect.html#if-you-are-on-different-networks">Stuzhik Connect</a>.</p><h2 id="problems" tabindex="-1">Problems <a class="header-anchor" href="#problems" aria-label="Permalink to &quot;Problems&quot;">​</a></h2><h3 id="outofmemoryerror" tabindex="-1">OutOfMemoryError <a class="header-anchor" href="#outofmemoryerror" aria-label="Permalink to &quot;OutOfMemoryError&quot;">​</a></h3><p><strong>The game ran out of the memory it was given.</strong> The <a href="/en/guide/log-analyzer.html">Log Analyzer</a> recognises this by itself and offers «Increase the allocated memory». By hand: the build&#39;s menu → «Edit» → memory (4-6 GB is usual for modpacks).</p><h3 id="the-game-won-t-launch" tabindex="-1">The game won&#39;t launch <a class="header-anchor" href="#the-game-won-t-launch" aria-label="Permalink to &quot;The game won&#39;t launch&quot;">​</a></h3><p>Open the build&#39;s «Analyze Logs» tab: the <a href="/en/guide/log-analyzer.html">analyzer</a> shows the main cause and what to do. Before a launch the launcher checks the build itself and warns about mods not for this game version or loader. It installs the Java it needs by itself.</p><h3 id="mods-don-t-load" tabindex="-1">Mods don&#39;t load <a class="header-anchor" href="#mods-don-t-load" aria-label="Permalink to &quot;Mods don&#39;t load&quot;">​</a></h3><p><strong>A mod must be for the build&#39;s loader and game version</strong>: the «Dependencies» tab lists other ones as «Not for this build», with a «Disable» button. If a mod needs another one (Fabric API, say), «Install all missing» is there too.</p><h3 id="crash-mentioning-mixin" tabindex="-1">Crash mentioning &quot;Mixin&quot; <a class="header-anchor" href="#crash-mentioning-mixin" aria-label="Permalink to &quot;Crash mentioning &quot;Mixin&quot;&quot;">​</a></h3><p><strong>Mods change the same game code, and one change did not apply.</strong> The Log Analyzer reads the report&#39;s <code>Mixins in Stacktrace</code> section and names the mods whose mixins changed the code that failed. Where mods step on each other&#39;s toes shows in advance on the <a href="/en/guide/mods.html#overlaps">«Overlaps»</a> tab.</p><h2 id="feedback" tabindex="-1">Feedback <a class="header-anchor" href="#feedback" aria-label="Permalink to &quot;Feedback&quot;">​</a></h2><h3 id="how-do-i-report-a-bug-or-suggest-a-feature" tabindex="-1">How do I report a bug or suggest a feature? <a class="header-anchor" href="#how-do-i-report-a-bug-or-suggest-a-feature" aria-label="Permalink to &quot;How do I report a bug or suggest a feature?&quot;">​</a></h3><p>Write to us on <a href="https://t.me/stuzhik_launcher" target="_blank" rel="noreferrer">Telegram</a>: update announcements are posted there too.</p>',64)])])}const f=t(n,[["render",i]]);export{m as __pageData,f as default};
